import type { Meta, StoryObj } from "@storybook/vue3";
import { KozmosContainer } from "../../index";

/**
 * Vue's Container: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. React's draw their content as JSX, so each is drawn here as React's
 * draws it; test/parity/container.parity.spec.ts holds Vue's render to
 * React's. Generated by `port Container`, then drawn by hand.
 */
type Args = Record<string, unknown>;

const meta: Meta<Args> = {
  title: "Vue/Core/Layout/Container",
  component: KozmosContainer,
};

export default meta;
type Story = StoryObj<Args>;

const withContent = (text: string) => (args: Args) => ({
  components: { KozmosContainer },
  setup: () => ({ args, text }),
  template: `
    <KozmosContainer v-bind="args">
      <div class="bg-muted p-4 border border-dashed text-center">{{ text }}</div>
    </KozmosContainer>
  `,
});

/** React's Default: centred, at most the widest page's width. */
export const Default: Story = {
  args: {},
  render: withContent("Container Content (Max Width 7xl)"),
};

/** React's Fluid: the full width. */
export const Fluid: Story = {
  args: { centered: false },
  render: withContent("Fluid Container (Full Width)"),
};

/**
 * Side by side: the same content in a page and in a 390px side panel. The
 * page's padding steps with the window; the panel's does not, because
 * `lg:px-8` reads the WINDOW and a narrow region inside a wide one was taking
 * the widest step — 32px each side on a desktop against a phone's 16.
 */
export const InAPanel: Story = {
  parameters: { layout: "fullscreen" },
  render: () => ({
    components: { KozmosContainer },
    // A side panel is 390 where there is room for one; below that the two
    // stack, because a fixed 390 beside anything overflows a phone.
    template: `
      <div class="flex flex-wrap gap-6 p-6">
        <div class="min-w-0 flex-1 basis-[280px]">
          <p class="mb-2 text-xs text-muted-foreground">inset="window" (the default)</p>
          <KozmosContainer :centered="false">
            <div class="border border-dashed bg-muted p-4 text-center">Page content</div>
          </KozmosContainer>
        </div>
        <div class="w-[390px] max-w-full rounded-container border">
          <p class="mb-2 p-2 text-xs text-muted-foreground">inset="panel"</p>
          <KozmosContainer :centered="false" inset="panel">
            <div class="border border-dashed bg-muted p-4 text-center">Panel content</div>
          </KozmosContainer>
        </div>
      </div>
    `,
  }),
};

/**
 * GAP-116: a region's own top and bottom space. A page column under a top
 * bar takes `block="sm"`, 16 above and below, rather than a Box around it;
 * PageHeader takes `{ start: "lg", end: "md" }`, 32 above and 24 below.
 */
export const BlockInset: Story = {
  parameters: { layout: "fullscreen" },
  render: () => ({
    components: { KozmosContainer },
    setup: () => ({
      blocks: ["sm", "md", "lg"],
      apart: 'block={{ start: "lg", end: "md" }}',
    }),
    template: `
      <div class="flex flex-col gap-6 p-6">
        <div v-for="block in blocks" :key="block" class="rounded-container border">
          <KozmosContainer :centered="false" inset="panel" :block="block">
            <div class="border border-dashed bg-muted p-4 text-center">block="{{ block }}"</div>
          </KozmosContainer>
        </div>
        <div class="rounded-container border">
          <KozmosContainer :centered="false" inset="panel" :block="{ start: 'lg', end: 'md' }">
            <div class="border border-dashed bg-muted p-4 text-center">{{ apart }}</div>
          </KozmosContainer>
        </div>
      </div>
    `,
  }),
};
